"$code = @'
using System;
using System.Windows.Automation;

public class UIAutoHelper {
    public static void InspectWindow() {
        AutomationElement root = AutomationElement.RootElement;
        Condition cond = new PropertyCondition(AutomationElement.NameProperty, "VSDC Video Editor");
        AutomationElement win = root.FindFirst(TreeScope.Children, cond);
        if (win == null) {
            Console.WriteLine("Window not found via UIAutomation");
            return;
        }
        Console.WriteLine("Found window: " + win.Current.Name + " (" + win.Current.ControlType.ProgrammaticName + ")");
        AutomationElementCollection children = win.FindAll(TreeScope.Descendants, Condition.TrueCondition);
        Console.WriteLine("Total descendants: " + children.Count);
        int shown = 0;
        foreach (AutomationElement child in children) {
            string name = child.Current.Name;
            string ctrlType = child.Current.ControlType.ProgrammaticName;
            if (!string.IsNullOrEmpty(name)) {
                Console.WriteLine(" - [" + ctrlType + "] '" + name + "'");
                shown++;
                if (shown >= 25) break;
            }
        }
    }
}
'@

