"import os
import sys
import re

for root in [os.getcwd(), r"D:\JRFK"]:
    session_dir = os.path.join(root, "session_logs")
    if os.path.exists(session_dir):
        for dirpath, dirnames, filenames in os.walk(session_dir):
            for f in filenames:
                if f.endswith(".jsonl") or f.endswith(".txt") or f.endswith(".log"):
                    p = os.path.join(dirpath, f)
                    try:
                        with open(p, "r", encoding="utf-8", errors="ignore") as fp:
                            content = fp.read()
                        new_content = re.sub(r"gh[pousr]_[A-Za-z0-9_]{16,}", "gho_REDACTED_TOKEN", content)
                        if new_content != content:
                            with open(p, "w", encoding="utf-8") as fp:
                                fp.write(new_content)
                            print("Sanitized:", p)
                    except Exception as e:
                        pass
"

